arguments.command:
cd /tmp/sv-551fd575ec12441d877f7bceaa611900

# Extract dynamic symbols sorted by address, then find nearest for our PCs
# Offsets: 0x222098, 0x222234, 0x19bac0, 0x19bc14
nm -D --defined-only symbols/libmonosgen-2.0.so | sort | awk '
BEGIN {
    targets[1] = 0x222098
    targets[2] = 0x222234
    targets[3] = 0x19bac0
    targets[4] = 0x19bc14
    ntargets = 4
}
{
    addr = strtonum("0x" $1)
    name = $3
    for (i = 1; i <= ntargets; i++) {
        if (addr <= targets[i]) {
            best_name[i] = name
            best_addr[i] = addr
        }
    }
}
END {
    for (i = 1; i <= ntargets; i++) {
        printf "0x%x -> %s+0x%x\n", targets[i], best_name[i], targets[i] - best_addr[i]
    }
}'

