arguments.command:
cd /tmp/sv-551fd575ec12441d877f7bceaa611900

# Get all dynamic symbols sorted, then for each target find the closest preceding symbol
nm -D --defined-only symbols/libmonosgen-2.0.so | sort > /tmp/mono_syms.txt

for offset in 0x222098 0x222234 0x19bac0 0x19bc14; do
    echo "=== PC offset $offset ==="
    # Find the symbol just before this address
    awk -v target="$offset" '
    BEGIN { tgt = strtonum(target) }
    {
        addr = strtonum("0x" $1)
        if (addr <= tgt) {
            last_addr = addr; last_name = $3
        }
    }
    END {
        printf "%s+0x%x (symbol at 0x%x)\n", last_name, tgt - last_addr, last_addr
    }' /tmp/mono_syms.txt
done

